/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `batch_scan_extracts` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `parent_id` bigint unsigned NOT NULL,
  `reference_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `subpoena_index` int unsigned NOT NULL DEFAULT '1',
  `file_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `storage_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `mime_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'application/pdf',
  `file_size_bytes` bigint unsigned DEFAULT NULL,
  `page_count` int unsigned DEFAULT NULL,
  `page_range_start` int unsigned DEFAULT NULL,
  `page_range_end` int unsigned DEFAULT NULL,
  `applicant_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `case_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `order_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ssn` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `date_of_birth` date DEFAULT NULL,
  `date_of_injury` date DEFAULT NULL,
  `customer` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `company_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `company_address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `specific_doctor` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `doctor_address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `record_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `requested_record` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `subpoena_date` date DEFAULT NULL,
  `date_requested` date DEFAULT NULL,
  `depo_due_date` date DEFAULT NULL,
  `amount` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cheque_date` date DEFAULT NULL,
  `cheque_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `extraction_confidence` json DEFAULT NULL,
  `raw_extraction` json DEFAULT NULL,
  `order_id` bigint unsigned DEFAULT NULL,
  `is_processed` tinyint(1) NOT NULL DEFAULT '0',
  `processed_at` datetime DEFAULT NULL,
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` bigint unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `extracted_facility_id` bigint unsigned DEFAULT NULL COMMENT 'Facility resolved from subpoena extraction customer field',
  `facility_mismatch` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 when extracted facility differs from parent chosen_facility_id',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_batch_scan_extracts_ref` (`reference_code`),
  KEY `idx_batch_scan_extracts_parent` (`parent_id`),
  KEY `idx_batch_scan_extracts_order_id` (`order_id`),
  KEY `idx_batch_scan_extracts_is_processed` (`is_processed`),
  KEY `idx_batch_scan_extracts_is_deleted` (`is_deleted`),
  KEY `fk_batch_scan_extracts_deleted_by` (`deleted_by`),
  KEY `idx_batch_scan_extracts_extracted_facility` (`extracted_facility_id`),
  KEY `idx_batch_scan_extracts_facility_mismatch` (`facility_mismatch`),
  CONSTRAINT `fk_batch_scan_extracts_deleted_by` FOREIGN KEY (`deleted_by`) REFERENCES `matrix_employees` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_batch_scan_extracts_extracted_facility` FOREIGN KEY (`extracted_facility_id`) REFERENCES `facilities` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_batch_scan_extracts_order` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_batch_scan_extracts_parent` FOREIGN KEY (`parent_id`) REFERENCES `unprocessed_subpoenas` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=296 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
