  `cancelled_by` bigint unsigned DEFAULT NULL COMMENT 'matrix_employees.id who cancelled the order',
  `court` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'WCAB',
