  `ssn_encrypted` varbinary(512) DEFAULT NULL COMMENT 'Encrypted SSN',
  `ssn_last_four` varchar(11) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Formatted SSN from order/subpoena (XXX-XX-1234 or ###-##-####); legacy rows may be 4 digits only',
  `dob` date DEFAULT NULL,
  `applicant_first_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `applicant_middle_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `applicant_last_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `applicant_aka` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
