  KEY `fk_orders_extracted_facility` (`extracted_facility_id`),
  KEY `idx_orders_patient_id` (`patient_id`),
  CONSTRAINT `fk_orders_batch_chosen_facility` FOREIGN KEY (`batch_chosen_facility_id`) REFERENCES `facilities` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_orders_cancelled_by` FOREIGN KEY (`cancelled_by`) REFERENCES `matrix_employees` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
